INSERT INTO "uc_catalogos" ("id", "fabricante_uc", "nome", "versao_catalogo", "descricao_comercial", "imagem_path", "ativo_comercial", "id_comercial") VALUES (1, 'Elgin', 'US 10 a 66HP - 2 e 3 Compressores', '02/2025', 'Disponível nas versões mecânica e Elétrica Completa, possui uma carenagem de fluxo de ar horizontal ou vertical e uma opção de 2 ou 3 compressores Scroll (Copeland) ou semi-herméticos (Dorin, Bitzer e Copeland). As opções incluem a instalação de um condensador a ar remoto ou controle de capacidade, degelo por gás quente e outros recursos que o tornam adequado para qualquer tipo de necessidade.', '/uploads/1b87c5cb3b224c3e89c2021764fe979d.jpg', TRUE, '4.1.1.1.1.1');
INSERT INTO "uc_catalogos" ("id", "fabricante_uc", "nome", "versao_catalogo", "descricao_comercial", "imagem_path", "ativo_comercial", "id_comercial") VALUES (2, 'Elgin', 'US 23 a 60HP - 1 Compressor', '01/2025', 'Disponível nas versões mecânica e Elétrica Completa, possui uma carenagem de fluxo de ar horizontal ou vertical e uma opção de 2 ou 3 compressores Scroll (Copeland) ou semi-herméticos (Dorin, Bitzer e Copeland). As opções incluem a instalação de um condensador a ar remoto ou controle de capacidade, degelo por gás quente e outros recursos que o tornam adequado para qualquer tipo de necessidade.', '/uploads/116e8cb64f9d43b283ed51661fd5ad3e.jpg', TRUE, '4.1.1.1.1.2');
INSERT INTO "uc_catalogos" ("id", "fabricante_uc", "nome", "versao_catalogo", "descricao_comercial", "imagem_path", "ativo_comercial", "id_comercial") VALUES (3, 'Elgin', 'US 6 a 20HP - 1 Compressor', '03/2025', 'A principal característica da Unidade condensadora US é a personalização. Disponível nas versões básica, mecânica completa e mecânica e elétrica completa, possui modelos com e sem carenagem e opção de compressores tipo Scroll (Elgin e Copeland) ou Semi-herméticos (Bitzer, Copeland e Dorin). Opcional: Separador de óleo, separador de liquido (acumulador), filtro na linha de sucção, válvula de serviço (entrada do tanque), isolamento da linha de sucção, Elgin Smart, controle de condensação, contatora do compressor relé de sobrecarga, relé de inversão e falta de fase, disjuntor controle de capacidade e degelo a gás quente.', '/uploads/58dafa8a78da4dfcaf20f26788ad99dc.jpg', TRUE, '4.1.1.1.1.3');